@Test
public void testStaticDirectory() {
    StateRouter router = new ConditionStateRouterFactory().getRouter(String.class, getRouteUrl(" => " + " host = " + NetUtils.getLocalHost()));
    List<StateRouter> routers = new ArrayList<StateRouter>();
    routers.add(router);
    List<Invoker<String>> originInvokers = new ArrayList<Invoker<String>>();
    Invoker<String> invoker1 = new MockInvoker<String>(URL.valueOf("dubbo://10.20.3.3:20880/com.foo.BarService"));
    Invoker<String> invoker2 = new MockInvoker<String>(URL.valueOf("dubbo://" + NetUtils.getLocalHost() + ":20880/com.foo.BarService"));
    Invoker<String> invoker3 = new MockInvoker<String>(URL.valueOf("dubbo://" + NetUtils.getLocalHost() + ":20880/com.foo.BarService"));
    originInvokers.add(invoker1);
    originInvokers.add(invoker2);
    originInvokers.add(invoker3);
    BitList<Invoker<String>> invokers = new BitList<>(originInvokers);
    List<Invoker<String>> filteredInvokers = router.route(invokers, URL.valueOf("consumer://" + NetUtils.getLocalHost() + "/com.foo.BarService"), new RpcInvocation(), false, new Holder<>());
    StaticDirectory<String> staticDirectory = new StaticDirectory<>(filteredInvokers);
    boolean isAvailable = staticDirectory.isAvailable();
    Assertions.assertTrue(!isAvailable);
    List<Invoker<String>> newInvokers = staticDirectory.list(new MockDirInvocation());
    Assertions.assertTrue(newInvokers.size() > 0);
    staticDirectory.destroy();
    Assertions.assertEquals(0, staticDirectory.getInvokers().size());
    Assertions.assertEquals(0, staticDirectory.getValidInvokers().size());
}

@Test
public void testBuildInvokerChainForLocalReference() {
    DefaultFilterChainBuilder defaultFilterChainBuilder = new DefaultFilterChainBuilder();
    // verify that no filter is built by default
    URL urlWithoutFilter = URL.valueOf("injvm://127.0.0.1/DemoService").addParameter(INTERFACE_KEY, DemoService.class.getName());
    urlWithoutFilter = urlWithoutFilter.setScopeModel(ApplicationModel.defaultModel());
    AbstractInvoker<DemoService> invokerWithoutFilter = new AbstractInvoker<DemoService>(DemoService.class, urlWithoutFilter) {

        @Override
        protected Result doInvoke(Invocation invocation) throws Throwable {
            return null;
        }
    };
    Invoker<?> invokerAfterBuild = defaultFilterChainBuilder.buildInvokerChain(invokerWithoutFilter, REFERENCE_FILTER_KEY, CONSUMER);
    Assertions.assertTrue(invokerAfterBuild instanceof AbstractInvoker);
    // verify that if LogFilter is configured, LogFilter should exist in the filter chain
    URL urlWithFilter = URL.valueOf("injvm://127.0.0.1/DemoService").addParameter(INTERFACE_KEY, DemoService.class.getName()).addParameter(REFERENCE_FILTER_KEY, "log");
    urlWithFilter = urlWithFilter.setScopeModel(ApplicationModel.defaultModel());
    AbstractInvoker<DemoService> invokerWithFilter = new AbstractInvoker<DemoService>(DemoService.class, urlWithFilter) {

        @Override
        protected Result doInvoke(Invocation invocation) throws Throwable {
            return null;
        }
    };
    invokerAfterBuild = defaultFilterChainBuilder.buildInvokerChain(invokerWithFilter, REFERENCE_FILTER_KEY, CONSUMER);
    Assertions.assertTrue(invokerAfterBuild instanceof FilterChainBuilder.CallbackRegistrationInvoker);
    Assertions.assertEquals(1, ((FilterChainBuilder.CallbackRegistrationInvoker<?, ?>) invokerAfterBuild).filters.size());
}

