    Assertions.assertEquals(0, Array.getLength(result));
    result = ArrayMerger.INSTANCE.merge(null, null);
    Assertions.assertEquals(0, Array.getLength(result));
    result = ArrayMerger.INSTANCE.merge(null, new Object[0]);
    Assertions.assertEquals(0, Array.getLength(result));
}

