    URL registeredConsumerUrl = urlToRegistry.addParameters(CATEGORY_KEY, CONSUMERS_CATEGORY, CHECK_KEY, String.valueOf(false)).setScopeModel(moduleModel);
    verify(registry, times(1)).register(registeredConsumerUrl);
}

