        }
        Assertions.assertTrue(client.isConnected());
        client.close(2000);
        server.close(2000);
    }
    {
        int port = NetUtils.getAvailablePort();
        Client client = startClient(port, 20000);
        Assertions.assertFalse(client.isConnected());
